SELECT  FROM stk_kline_daily
WHERE symbol_type = #{symbolType} AND symbol_code = #{symbolCode}
AND trade_date BETWEEN #{startDate} AND #{endDate}
ORDER BY trade_date

SELECT  FROM stk_kline_daily
WHERE symbol_type = #{symbolType} AND symbol_code = #{symbolCode}
ORDER BY trade_date DESC
LIMIT #{limit}

