    open_price = #{openPrice}, high_price = #{highPrice},
    low_price = #{lowPrice}, close_price = #{closePrice},
    pre_close = #{preClose}, volume = #{volume}, amount = #{amount},
    change_pct = #{changePct}, amplitude = #{amplitude}, turnover_rate = #{turnoverRate}

